import os
import stat
from pathlib import Path

import pytest

NOTES_DIR: str = "notes"


def count_readable(names: list[str]) -> int:
    """Return how many entries of names are readable regular files inside NOTES_DIR.

    Each name is a file name relative to NOTES_DIR. Names that are missing,
    unreadable, directories, or that resolve outside NOTES_DIR (via "..",
    absolute paths, or symlinks) are not counted and never read from.
    """
    base = Path(NOTES_DIR).resolve()
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    count = 0
    for name in names:
        if "\x00" in name:
            continue
        try:
            candidate = (base / name).resolve()
        except (OSError, RuntimeError, ValueError):
            continue
        if candidate == base or not candidate.is_relative_to(base):
            continue
        try:
            fd = os.open(candidate, os.O_RDONLY | nofollow)
        except OSError:
            continue
        try:
            if stat.S_ISREG(os.fstat(fd).st_mode):
                count += 1
        except OSError:
            pass
        finally:
            os.close(fd)
    return count


@pytest.fixture
def notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / NOTES_DIR
    d.mkdir()
    return d


def test_counts_readable_files(notes_dir: Path) -> None:
    (notes_dir / "a.txt").write_text("alpha")
    (notes_dir / "b.txt").write_text("beta")
    assert count_readable(["a.txt", "b.txt", "missing.txt"]) == 2


def test_empty_list_gives_zero(notes_dir: Path) -> None:
    assert count_readable([]) == 0


def test_directory_is_not_counted(notes_dir: Path) -> None:
    (notes_dir / "sub").mkdir()
    assert count_readable(["sub"]) == 0


def test_parent_traversal_not_counted(tmp_path: Path, notes_dir: Path) -> None:
    (tmp_path / "secret.txt").write_text("top secret")
    assert count_readable(["../secret.txt", "../notes/../secret.txt"]) == 0


def test_absolute_path_not_counted(tmp_path: Path, notes_dir: Path) -> None:
    secret = tmp_path / "secret.txt"
    secret.write_text("top secret")
    assert count_readable([str(secret)]) == 0


def test_symlink_escaping_notes_not_counted(tmp_path: Path, notes_dir: Path) -> None:
    secret = tmp_path / "secret.txt"
    secret.write_text("top secret")
    os.symlink(secret, notes_dir / "link.txt")
    assert count_readable(["link.txt"]) == 0


def test_nul_byte_in_name_does_not_raise(notes_dir: Path) -> None:
    (notes_dir / "a.txt").write_text("alpha")
    assert count_readable(["a\x00.txt", "a.txt"]) == 1


def test_unreadable_file_not_counted(notes_dir: Path) -> None:
    if hasattr(os, "geteuid") and os.geteuid() == 0:
        pytest.skip("root can read mode-000 files")
    locked = notes_dir / "locked.txt"
    locked.write_text("hidden")
    locked.chmod(0o000)
    try:
        assert count_readable(["locked.txt"]) == 0
    finally:
        locked.chmod(0o644)
